/* src/styles/i18n-fonts.css
 * Per-language font switching, driven by the data-lang attribute that
 * src/i18n.js sets on <html> for every language change.
 * Import this in your index.css:  @import "./styles/i18n-fonts.css";
 * And add the <link> for Noto fonts in index.html (see README).
 */

:root {
