          {...rise(0.08)}
          className="mt-6 text-4xl font-bold leading-tight text-copper-400 [text-shadow:0_2px_30px_rgba(200,134,42,0.25)] sm:text-6xl md:text-7xl"
        >
          {t("hero.name")}
        </motion.h1>

        <motion.p
          {...rise(0.16)}
          className="mx-auto mt-5 max-w-2xl text-lg text-pcb-100/90 sm:text-xl"
